  pages = {
    ["archesonus"] = {
      title = "Historienne royale Archesonus",
      text = {
        { "Vous m'avez donc trouvée. Je garde l'histoire de Forgefer depuis le Haut-Siège, à quelques pas du trône du roi Magni, et quiconque m'interroge à son sujet ferait bien d'avoir un après-midi devant lui." },
        { "L'histoire qu'on me demande le plus, c'est celle des Sombrefer. La guerre des Trois Marteaux s'acheva quand le thane-sorcier Thaurissan appela Ragnaros, et le réveil du seigneur du Feu réduisit leur propre pays en cendres. Des reliques gisent encore dans les ruines de Thaurissan, dans les Steppes ardentes, et elles en savent plus sur cette histoire que je n'ai pu en lire. Qui me rapportera ce qu'elles disent aura toute ma gratitude." },
        { "Ce registre est mon œuvre, $gvoyageur:voyageuse;, avec beaucoup d'aide de la Ligue des explorateurs, qui rapporte plus de choses qu'une seule historienne n'en pourrait lire. Si une page vous a bien servi, j'en suis heureuse. Si l'une d'elles vous a fait défaut, venez me le dire." },
        { side = "Horde", aside = true, sign = "P. F.", "Je ne l'ai jamais rencontrée. Son récit du monde reste le plus équitable que j'aie lu sous une plume vivante." },
      },
    },
    ["coldridge-valley"] = {
      title = "Vallée des Frigères",
      text = {
        { "Courbenclume rassemble les recrues naines et gnomes dans la vallée des Frigères, au sud de Kharanos. Elles y trouvent leurs instructeurs, leurs premiers ordres, et la passe qui les mènera au-delà, dans Dun Morogh. Un début modeste, peut-être, mais toute route en a un." },
        { "Ces ordres ne se limitent pas à l'entraînement. Les troggs Mâcheroc menacent la vallée, les trolls Frostmane ont établi un camp tout près, et Balir Frosthammer et Grelin Whitebeard ont besoin d'aide contre eux. Gardez votre arme à portée de main, $gvoyageur:voyageuse;. On a besoin des recrues avant même qu'elles aient quitté la vallée." },
      },
    },
    ["deeprun-tram"] = {
      title = "Le Tram des profondeurs",
      text = {
        { "Le Tram des profondeurs transporte ses passagers entre Forgefer et Hurlevent sur des plates-formes mobiles, sous la terre. Il a réduit un voyage de plusieurs jours à une affaire de minutes. Même un nain qui aime marcher sait apprécier une telle prouesse." },
        { "Le tunnel donne à notre amitié avec Hurlevent une forme bien concrète : deux capitales reliées par une voie qui épargne à leurs voyageurs la longue route par la surface. L'ingéniosité gnome a sauvé bien des paires de bottes." },
        { "Surveillez les vitres là où le tunnel passe sous l'eau, $gvoyageur:voyageuse;. Certains passagers disent avoir vu quelque chose de très grand les regarder en retour. Vous devriez avoir le temps d'y jeter un œil avant que la plate-forme ne vous emporte." },
      },
    },
    ["dun-morogh"] = {
      title = "Dun Morogh",
      text = {
        { "Dun Morogh, ce sont les hautes terres enneigées autour de Forgefer, patrie des nains du clan Bronzebeard et de leurs voisins gnomes." },
        { "Ces terres sont à nous, mais nous les partageons, et pas toujours de bon gré. Les trolls Frostmane tiennent les collines de l'ouest, les troggs creusent où bon leur semble, et depuis la chute de Gnomeregan les gnomes sont nos voisins dans leurs propres vallées autant que dans notre cité." },
        { "Apprenez bien ses routes, $gvoyageur:voyageuse;. La plupart des nains que vous rencontrerez un jour y ont fait leurs premiers pas." },
      },
    },
    ["explorers-league"] = {
      title = "La Ligue des explorateurs",
      text = {
        { "Je pouvais difficilement oublier la Ligue. La Ligue des explorateurs est la société d'historiens, d'archéologues et de fouilleurs de Forgefer : ces nains qui aiment mieux lire une ruine que bâtir une salle. Une historienne royale ne saurait rêver meilleure compagnie." },
        { "Ils poursuivent la plus vieille question qui soit : d'où viennent les nains. Leurs fouilles à Uldaman laissent penser que la réponse se trouve du côté des Titans, les façonneurs du monde, et s'il en est ainsi, cela change la manière dont chaque nain devrait se voir. Le roi Magni prend la chose très au sérieux." },
        { "Vous les trouverez dans le Hall des Explorateurs, sous la direction du grand explorateur Magellas. Apportez-leur tout ce qui est ancien, $gvoyageur:voyageuse;, et tout ce qui est étrange. Ils voudront savoir où vous l'avez trouvé, et moi aussi." },
      },
    },
    ["frostmane-trolls"] = {
      title = "Les trolls Frostmane",
      text = {
        { "Les Frostmane occupent le pays enneigé à l'ouest de Kharanos, avec des camps jusque dans la vallée des Frigères. Leur repaire abrite des chasseurs de têtes, des voyants et des lanceurs d'ombre, si bien que les montagnards ont plus que des pointes de lance à guetter entre les congères." },
        { "Grelin Whitebeard met en garde contre de nouvelles attaques, et les jeunes nains sont envoyés contre eux presque dès qu'ils quittent la maison. La querelle devient vite familière : un camp troll au-delà du dernier feu ami, un rapport remis aux gardes, et une nouvelle patrouille envoyée dans la même neige." },
      },
    },
    ["gates-of-ironforge"] = {
      title = "Les portes de Khaz Modan",
      text = {
        { "Les passages de la porte Nord et de la porte Sud mènent les voyageurs de Dun Morogh au Loch Modan. Des montagnards tiennent des avant-postes sur les deux routes. En montagne, une route étroite peut exiger autant de gardes qu'une large frontière." },
        { "Le capitaine Rugelfuss expose la difficulté depuis le côté du Loch Modan. Son régiment doit tenir la porte plutôt que de pourchasser les troggs voisins, tandis que la Réserve de Forgefer est engagée sur le front de l'Alliance. Il demande aux aventuriers de défendre les terres que ses soldats ne peuvent couvrir sans quitter leur poste." },
      },
    },
    ["gnomeregan"] = {
      title = "Gnomeregan",
      text = {
        { "Gnomeregan s'étend sous l'ouest de Dun Morogh : l'ancienne capitale des gnomes, ruinée pendant la crise de la Troisième Guerre. Des troggs envahirent ses salles. Pour les arrêter, les gnomes répandirent des radiations dans leur propre cité." },
        { "Les troggs survécurent. Beaucoup de gnomes moururent, et d'autres furent changés en ces survivants violents qu'on appelle aujourd'hui gnomes lépreux. Ceux qui en réchappèrent trouvèrent refuge à Forgefer. Ce qu'a coûté la tentative se lit encore dans les salles empoisonnées." },
        { "Sicco Thermaplugg y est resté. Le grand bricoleur Mekkatorque le traite de traître et demande aux aventuriers de le tuer. Si vous y entrez, $gvoyageur:voyageuse;, souvenez-vous que c'était une capitale pleine de foyers et d'ateliers. Son peuple essaie encore de sauver ce qu'il en reste." },
      },
    },
    ["gnomeregan-exiles"] = {
      title = "Les Exilés de Gnomeregan",
      text = {
        { "Un peuple sans foyer, et les exilés les plus joyeux que vous rencontrerez jamais. Les gnomes qui ont fui Gnomeregan vivent désormais à Brikabrok, au cœur de Forgefer, et dans des avant-postes comme le dépôt de Steelgrill, en vue de leurs anciennes portes." },
        { "Ne vous laissez pas tromper par leur gaieté. Chaque invention qu'ils essaient, chaque recrue qu'ils forment, prépare un seul jour : celui où ils marcheront sur Gnomeregan pour la reprendre." },
        { "Forgefer leur a offert un abri aussi longtemps qu'il le faudra. La plupart des nains apprécient leur compagnie, sinon leur vacarme." },
      },
    },
    ["hall-of-thanes"] = {
      title = "La salle des Thanes",
      text = {
        { "Sous Forgefer s'étendent les cavernes du Vieux Forgefer, et parmi elles un lieu que les nains appellent la salle des Thanes. Les Sombrefer en ont trouvé le chemin. Une carte prise à leurs espions à la base d'Ironband montre des tunnels et d'anciennes routes qui convergent sous la cité, et le terre-voyant Farsen, venu du Nid-de-l'Aigle, les a suivis jusqu'à la salle et jusqu'au Sombrefer qui y commande, un certain Durgen Dirgehammer." },
        { "Les morts de la salle ne sont pas en paix. Afadra Mur-de-Dun, gardienne du savoir de Forgefer, demande aux voyageurs d'apaiser les esprits de Courbenclume, et l'un d'eux, Faldrim Courbenclume, semble avoir gardé une vieille rancune bien au-delà de la tombe. Le roi Magni veut la tête du commandant. J'aimerais que la Ligue examine les lieux comme il se doit, une fois les Sombrefer partis." },
      },
    },
    ["high-tinker-mekkatorque"] = {
      title = "Grand Bricoleur Mekkatorque",
      text = {
        { "Gelbin Mekkatorque dirige les gnomes depuis Brikabrok, à Forgefer. Les nains ont donné un refuge à son peuple, mais leur propre capitale reste sous Dun Morogh. Un foyer emprunté à des amis ne saurait effacer la perte de Gnomeregan." },
        { "Les radiations répandues contre les troggs qui l'envahissaient n'ont pas su les exterminer et ont dévasté les gnomes eux-mêmes. Mekkatorque faisait jadis confiance à Sicco Thermaplugg ; il l'accuse aujourd'hui d'avoir trahi la cité et demande aux aventuriers d'y entrer pour le tuer." },
      },
    },
    ["ironforge"] = {
      title = "Forgefer",
      text = {
        { "Forgefer n'est pas bâtie sur la montagne : elle est bâtie dedans. Ses salles sont creusées au cœur de la montagne, et en son centre brûle la Grande forge." },
        { "La cité tourne autour de la forge comme une roue. Le roi Magni tient sa cour au Haut-Siège, la Garde militaire forme les défenseurs de la montagne, les mages se tiennent à la Garde mystique, et depuis la chute de Gnomeregan les gnomes exilés ont fait de Brikabrok leur domaine : bruyant, ingénieux et nostalgique. Sous tout cela court le Tram des profondeurs, œuvre gnome, qui emmène les voyageurs sous les montagnes jusqu'à Hurlevent." },
        { client = "forever", "Sous le Vieux Forgefer s'étend la salle des Thanes. Des intrus sombrefer y ont fait une brèche, et Magni veut la tête de leur commandant, Durgen Dirgehammer. Même ici, les plus vieilles salles d'une cité peuvent devenir ses plus récents soucis." },
        { "Et puis il y a le Hall des Explorateurs, où la Ligue garde sa bibliothèque et ses trouvailles : des reliques d'Uldaman, les ossements de bêtes que personne n'a vues vivantes, et des cartes de lieux que la plupart des nains ne connaîtront jamais que par les livres. Quant à moi, vous me trouverez au Haut-Siège, à quelques pas du trône du roi. Venez me voir. Je manque toujours de gens qui sont vraiment allés quelque part." },
        { side = "Horde", aside = true, sign = "P. F.", "Son invitation part d'un bon sentiment. Je ne conseillerais pas de l'accepter aux couleurs de la Horde." },
      },
    },
    ["kharanos"] = {
      title = "Kharanos",
      text = {
        { "Kharanos se trouve dans le cœur glacé de Dun Morogh, sur la route entre les terrains d'entraînement de la vallée des Frigères et les portes de Forgefer. C'est une petite ville, à l'aune des nains : une forge, quelques solides maisons, et le bâtiment qui fait sa renommée, la distillerie Thunderbrew, où la famille Thunderbrew perfectionne ses bières depuis plus longtemps que quiconque ne veut l'admettre." },
        { "Ne prenez pas la chaleur du foyer pour de la sécurité. Les trolls Frostmane tiennent les collines de l'ouest, les troggs ne cessent de remonter des profondeurs, et depuis la chute de Gnomeregan ses exilés partagent ces routes avec nous. La ville garde pourtant ses portes ouvertes : un nain qui ferme sa porte à un voyageur transi n'en est pas un." },
      },
    },
    ["leper-gnomes"] = {
      title = "Les gnomes lépreux",
      text = {
        { "Tous les gnomes n'ont pas fui Gnomeregan. Certains ont survécu aux radiations et en ont été changés, le corps ravagé et l'esprit devenu étrange et violent. Les nains les appellent gnomes lépreux, et les exilés n'aiment pas du tout parler d'eux." },
        { "Ils hantent les abords de l'ancienne cité et les dépôts alentour, récupérant ce qu'ils peuvent et attaquant quiconque s'approche trop." },
        { "Si vous devez les combattre, $gvoyageur:voyageuse;, souvenez-vous qu'ils furent un jour les voisins de quelqu'un." },
      },
    },
    ["magni-bronzebeard"] = {
      title = "Roi Magni Bronzebeard",
      text = {
        { "Le roi Magni Bronzebeard tient sa cour au Haut-Siège de Forgefer et règne sur la cité qui appartient à son clan depuis la guerre des Trois Marteaux. Il est l'aîné de trois frères. Muradin est parti vers le nord avec le prince de Lordaeron pendant la Troisième Guerre, et l'on est sans nouvelles de lui depuis. Brann est l'explorateur le plus célèbre de la Ligue, et l'un des plus difficiles à suivre à la trace." },
        { "Magni suit de près les travaux de la Ligue. Les trouvailles d'Uldaman laissent penser que les nains furent façonnés il y a bien longtemps par les Titans. Un roi d'une si longue lignée a de bonnes raisons de demander où elle commence, et une historienne qui se tient à quelques pas de son trône a toutes les raisons de saluer son intérêt." },
        { "Sa fille lui cause un souci plus pressant. La princesse Moira se trouve dans la cité sombrefer sous le mont Rochenoire, mariée à l'empereur Dagran Thaurissan. Forgefer parle d'enlèvement, et Magni promet une récompense digne d'un héros à qui la ramènera. Si vous acceptez cette charge, $gvoyageur:voyageuse;, vous portez les espoirs d'un père autant que les ordres d'un roi." },
      },
    },
    ["mekgineer-thermaplugg"] = {
      title = "Mekgénieur Thermaplugg",
      text = {
        { "Sicco Thermaplugg est resté à Gnomeregan tandis que le grand bricoleur Mekkatorque mène ses exilés depuis Forgefer. Le grand bricoleur lui faisait jadis confiance. Cette confiance a fini en accusation de trahison, et en appel à sa mort." },
        { "Les radiations répandues dans la cité n'ont pas su exterminer les troggs et ont dévasté ses habitants gnomes. Thermaplugg règne dans les ruines, parmi les créatures que la tentative devait détruire et les survivants qu'elle a laissés derrière elle." },
        { "Mekkatorque demande aux aventuriers de porter son jugement dans ces salles." },
      },
    },
    ["timber"] = {
      title = "Grumeux",
      text = {
        { "Les chasseurs de Kharanos l'appellent Grumeux : un loup plus grand que ses congénères, qui comprend les pièges un peu trop bien. On dit qu'il choisit son terrain et revient sur ses propres traces. Il a survécu à tous les chasseurs lancés à ses trousses." },
        { "Les loups figurent rarement dans une histoire royale. Celui-ci a plaidé sa cause avec assez d'arguments pour y entrer, même si je doute qu'il apprécie l'honneur." },
        { "Si vous l'avez tué, $gvoyageur:voyageuse;, notez ce qui s'est passé tant que vous vous en souvenez. Les chasseurs auront bien assez tôt leur propre version." },
      },
    },
    ["war-of-the-three-hammers"] = {
      title = "La guerre des Trois Marteaux",
      text = {
        { "Il y a quelque deux siècles et demi, Forgefer appartenait à trois clans à la fois. Les Bronzebeard, les Wildhammer et les Sombrefer vivaient sous un même haut roi, Modimus Courbenclume, et à sa mort ils ne purent s'entendre sur son successeur." },
        { "La querelle devint une guerre sous la montagne. Les Bronzebeard tinrent la cité. Les Wildhammer, menés par le thane Khardros, en furent chassés et élevèrent leur propre forteresse à Grim Batol, et les Sombrefer du thane-sorcier Thaurissan se retirèrent dans les montagnes du sud." },
        { "Les Sombrefer n'en avaient pas fini. Ils marchèrent à la fois sur Forgefer et sur Grim Batol, et perdirent les deux batailles. Dans sa fureur, Thaurissan fit appel à une puissance bien plus ancienne que n'importe quel clan et réveilla Ragnaros, le seigneur du Feu. Le sud brûla : la gorge des Vents brûlants et les Steppes ardentes sont ce qu'il en resta, et depuis, les Sombrefer servent le seigneur du Feu dans le mont Rochenoire." },
        { "Les Wildhammer ne restèrent pas non plus à Grim Batol. La mort de la reine Modgud, tuée à ses portes, laissa une noirceur dans la pierre, et ils se firent un nouveau foyer au Nid-de-l'Aigle, dans les Hinterlands. Forgefer se souvient encore de quel clan est resté." },
      },
    },
    ["wendigos"] = {
      title = "Les wendigos",
      text = {
        { "L'antre Gris offre un abri contre la neige de Dun Morogh, pourvu que vous parveniez à convaincre ses wendigos de le partager. Un coursier qui les a fuis y a laissé derrière lui une cargaison de munitions. Les créatures ont eu le dernier mot." },
        { "Le pilote Stonegear veut leurs crinières pour en faire un tapis dans son engin de siège. Même une machine a besoin d'un peu de confort dans ce pays, $gvoyageur:voyageuse;. Pour récupérer les munitions comme pour meubler l'engin, il faut approcher un wendigo de bien plus près que le coursier n'a voulu le faire." },
      },
    },
  },
})
